package com.brightloop.auth;
import com.brightloop.user.*;import jakarta.mail.MessagingException;import jakarta.mail.internet.MimeMessage;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.Duration;import java.time.Instant;import java.util.HexFormat;import java.util.UUID;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.mail.javamail.MimeMessageHelper;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class PasswordResetService{
 private static final Logger log=LoggerFactory.getLogger(PasswordResetService.class);private final AppUserRepository users;private final PasswordResetTokenRepository tokens;private final PasswordEncoder encoder;private final ObjectProvider<JavaMailSender> mail;private final boolean exposeToken,mailEnabled;private final String frontendUrl;
 public PasswordResetService(AppUserRepository u,PasswordResetTokenRepository t,PasswordEncoder e,ObjectProvider<JavaMailSender> m,@Value("${brightloop.password-reset.expose-token:false}") boolean expose,@Value("${brightloop.mail.enabled:false}") boolean mailEnabled,@Value("${FRONTEND_BASE_URL:http://localhost:5173}") String frontendUrl){users=u;tokens=t;encoder=e;mail=m;exposeToken=expose;this.mailEnabled=mailEnabled;this.frontendUrl=frontendUrl;}
 public record ForgotResponse(String message,String developmentToken){}
 @Transactional public ForgotResponse request(String email){String generic="If the account exists, password reset instructions have been sent.";var user=users.findByEmailIgnoreCase(email.trim());if(user.isEmpty())return new ForgotResponse(generic,null);String raw=UUID.randomUUID()+"-"+UUID.randomUUID();tokens.deleteByUserId(user.get().getId());tokens.save(new PasswordResetToken(user.get().getId(),hash(raw),Instant.now().plus(Duration.ofMinutes(30))));String url=frontendUrl+"/?resetToken="+raw;if(mailEnabled){try{send(user.get().getEmail(),url);}catch(Exception ex){log.error("Password reset email could not be sent",ex);}}else if(exposeToken){log.info("Development password reset URL: {}",url);}return new ForgotResponse(generic,exposeToken?raw:null);}
 @Transactional public void reset(String raw,String newPassword){var token=tokens.findByTokenHash(hash(raw)).filter(PasswordResetToken::valid).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reset token is invalid or expired"));var user=users.findById(token.getUserId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reset token is invalid or expired"));user.changePassword(encoder.encode(newPassword));token.consume();}
 private void send(String email,String url)throws MessagingException{JavaMailSender sender=mail.getIfAvailable();if(sender==null)throw new IllegalStateException("SMTP is enabled but no mail sender is configured");MimeMessage message=sender.createMimeMessage();MimeMessageHelper helper=new MimeMessageHelper(message,false,StandardCharsets.UTF_8.name());helper.setTo(email);helper.setSubject("Reset your Brightloop password");helper.setText("Use this secure link within 30 minutes to reset your password: "+url,false);sender.send(message);}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
